globalGitCredentialForm.addEventListener("submit", async (event) => { event.preventDefault(); if (saveGitCredentialButton.disabled) return; saveGitCredentialButton.disabled = true; saveGitCredentialButton.textContent = "Saving…"; gitCredentialError.hidden = true; try { const type = globalGitType.value; let credential; if (type === "ssh") { const privateKey = $("#global-ssh-key").value; const knownHosts = $("#global-known-hosts").value; const username = $("#global-ssh-username").value.trim(); const extraConfig = $("#global-ssh-config").value.trim(); if (!privateKey.trim() || !knownHosts.trim()) throw new Error("Private key and Known Hosts are required."); if (username && !/^[A-Za-z0-9._-]+$/.test(username)) throw new Error("SSH username contains unsupported characters."); const sshConfig = [username ? `User ${username}` : "", extraConfig].filter(Boolean).join("\n"); credential = { name: $("#global-git-name").value.trim(), type, privateKey, knownHosts, ...(sshConfig ? { sshConfig } : {}) }; } else { credential = { name: $("#global-git-name").value.trim(), type, username: $("#global-https-username").value, password: $("#global-https-password").value }; } await jsonFetch("/api/git-credentials", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(credential) }); globalGitCredentialForm.reset(); globalGitType.onchange(); await renderGitCredentials(); } catch (error) { gitCredentialError.textContent = error instanceof Error && error.message === "SSH username contains unsupported characters." ? error.message : "Could not save Git credential. Check the name, secret, Known Hosts, and SSH config fields."; gitCredentialError.hidden = false; } finally { $("#global-ssh-key").value = ""; $("#global-known-hosts").value = ""; $("#global-ssh-username").value = ""; $("#global-ssh-config").value = ""; $("#global-https-username").value = ""; $("#global-https-password").value = ""; saveGitCredentialButton.disabled = false; globalGitType.onchange(); } });
identityForm.addEventListener("submit", async (event) => { event.preventDefault(); try { await jsonFetch("/api/identity/allowed", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ displayName: $("#identity-name").value, identity: $("#identity-value").value, publicKey: $("#identity-public-key").value, algorithm: "ed25519" }) }); identityForm.reset(); await renderSettings(); } catch (error) { systemInfo.textContent = error instanceof Error ? error.message : "Identity update failed."; } });

(async () => { if (!await ensureAuth()) return; app.hidden = false; loadPersisted(); await loadTargets(); await loadNodes(); await loadModels(); await loadSessions(); const requestedSession = new URLSearchParams(location.search).get("session"); const linked = [...state.sessions.values()].find((session) => session.sessionId === requestedSession); if (linked) { state.activeSessionId = linked.id; state.selectedNodeId = linked.targetId; await loadModels(); } connectApplicationEvents(); if (state.activeSessionId) { await activateSession(state.activeSessionId); } else { await openNewSession("local", state.defaultModelRef); } setInterval(async () => { await loadNodes(); await loadSessions(); for (const session of state.sessions.values()) { await refreshSession(session); await loadApprovals(session); } renderTabs(); renderAttention(); }, 5000); })().catch((error) => { app.hidden = false; workspace.hidden = true; emptyState.hidden = false; emptyState.querySelector(".welcome-description").textContent = error instanceof Error ? error.message : "Porta could not load."; });
